import hashlib, json, requests

API_KEY = "your_api_key"
# 平台底层维护了多个上游账号，为了保证亲和性 cache_task_id 参数配置能保证 cache 缓存命中率, 具体参数解释 https://iwiki.woa.com/p/4051772719 务必替换成cache_task_id=<32位MD5>
CACHE_TASK_ID = hashlib.md5(f"chat_demo:{API_KEY}".encode()).hexdigest()
URL = "http://api.aihub.woa.com/standard/v1/chat/completions"
HEADERS = {
    "Content-Type": "application/json",
    "Authorization": f"Bearer {API_KEY}?cache_task_id={CACHE_TASK_ID}",
    # "Authorization": f"Bearer {API_KEY}?provider=minimax&cache_task_id={CACHE_TASK_ID}",
}

body = {
    "model": "minimax-m3.1-flash",
    "messages": [
        {"role": "system", "content": "你是简洁的中文助手"},
        {"role": "user", "content": [
            {"type": "text", "text": "用一句话解释什么是分布式锁"},
        ]},
    ],
    "reasoning_effort": "medium",
    "max_completion_tokens": 4096,
    "stream": False,
    # "stream_options": {"include_usage": True},
    # "tools": [{
    #     "type": "function",
    #     "function": {
    #         "name": "get_weather",
    #         "description": "获取城市天气",
    #         "parameters": {
    #             "type": "object",
    #             "properties": {
    #                 "city": {"type": "string", "description": "城市名"}},
    #             "required": ["city"],
    #         },
    #     },
    # }],
}

# body["messages"][1]["content"].append({"type": "image_url", "image_url": {
#     "url": ("https://help-static-aliyun-doc.aliyuncs.com/"
#             "file-manage-files/zh-CN/20241022/emyrja/dog_and_girl.jpeg")}})
# body["messages"][1]["content"].append({"type": "image_url", "image_url": {
#     "url": ("data:image/png;base64,"
#             "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAA"
#             "DElEQVR4nGP4z8AAAAMBAQDJ/pLvAAAAAElFTkSuQmCC")}})
# body["messages"][1]["content"].append({"type": "video_url", "video_url": {
#     "url": ("https://filecdn.minimax.chat/public/"
#             "ee8c1648-21f1-41b7-8397-65022d22ffe5.mp4")}})

r = requests.post(URL, headers=HEADERS, json=body, timeout=300,
                  stream=body["stream"])
r.raise_for_status()
r.encoding = "utf-8"

if body["stream"]:
    for line in r.iter_lines(decode_unicode=True):
        if not line.startswith("data: ") or line == "data: [DONE]":
            continue
        for choice in json.loads(line[6:]).get("choices") or []:
            delta = choice.get("delta") or {}
            print(delta.get("reasoning_content") or delta.get("content") or "",
                  end="", flush=True)
    print()
else:
    print(json.dumps(r.json(), ensure_ascii=False, indent=2))

